class FakeRuntime:
    constructions = 0

    def __init__(self, checkpoint, sha256, progress):
        type(self).constructions += 1
        self.checkpoint = worker.verify_checkpoint(checkpoint, sha256)
        self.identity = worker.checkpoint_identity(checkpoint)
        self.sha256 = sha256.lower()
        self.startup_timings = {"constructions": type(self).constructions}

    def analyze(self, audio, sample_rate, frames, progress):
        if worker.checkpoint_identity(self.checkpoint) != self.identity:
            raise worker.CheckpointChangedError("Checkpoint changed")
        if Path(audio).stat().st_size != frames * 4:
            raise ValueError("Audio frame count mismatch")
        marker = struct.unpack("=f", Path(audio).read_bytes()[:4])[0]
        if marker < 0:
            raise ValueError("Synthetic model failure")
        progress(0.1)
        progress(1.0)
        return {
            "version": 1,
            "model_sha256": self.sha256,
            "beats": [marker, marker + 0.5],
            "downbeats": [marker],
        }, {"job_seconds": 0.001}


class ServerProtocolTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.root = Path(self.directory.name)
        self.checkpoint = self.root / "model.ckpt"
        self.checkpoint.write_bytes(b"verified checkpoint")
        self.digest = hashlib.sha256(self.checkpoint.read_bytes()).hexdigest()
        self.audio = self.root / "audio.f32"
        self.audio.write_bytes(struct.pack("=f", 0.1) * 16000)

    def request(self, identifier="a", **changes):
        return {
            "protocol": 2,
            "type": "analyze",
            "id": identifier,
            "audio": str(self.audio),
            "sample_rate": 8000,
            "frames": 16000,
            **changes,
        }

    def start_server(self, env=None):
        code = (
            "import sys; from types import SimpleNamespace; "
            "from tools.test_beat_this_worker import worker, FakeRuntime; "
            "sys.exit(worker.serve(SimpleNamespace(checkpoint=sys.argv[1], "
            "sha256=sys.argv[2]), runtime_factory=FakeRuntime))"
        )
        process = subprocess.Popen(
            [sys.executable, "-c", code, str(self.checkpoint), self.digest],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            env=env,
            cwd=WORKER.parents[2],
        )
        self.addCleanup(
            lambda: process.kill() if process.poll() is None else None
        )
        return process

    def transact(self, lines):
        process = self.start_server()
        text = "".join(
            (line if isinstance(line, str) else json.dumps(line)) + "\n"
            for line in lines
        )
        output, errors = process.communicate(text, timeout=10)
        self.assertEqual("", errors)
        return process.returncode, [
            json.loads(line) for line in output.splitlines()
        ]

    def test_protocol_uses_utf8_even_when_host_stdio_defaults_to_ascii(self):
        self.audio = self.root / "Tänzer.f32"
        self.audio.write_bytes(struct.pack("=f", 0.1) * 16000)
        environment = dict(os.environ, PYTHONIOENCODING="ascii")
        process = self.start_server(environment)
        request = json.dumps(self.request("takt-ä"), ensure_ascii=False) + "\n"
        output, errors = process.communicate(request, timeout=10)
        self.assertEqual(0, process.returncode, errors)
        messages = [json.loads(line) for line in output.splitlines()]
        results = [
            message for message in messages if message["type"] == "result"
        ]
        self.assertEqual(["takt-ä"], [message["id"] for message in results])

    def test_two_jobs_share_loaded_worker_and_progress_has_correct_ids(self):
        code, messages = self.transact(
            [
                self.request("first"),
                self.request("second"),
                {"protocol": 2, "type": "shutdown"},
            ]
        )
        self.assertEqual(0, code)
        self.assertEqual(1, sum(x["type"] == "ready" for x in messages))
        self.assertEqual(1, messages[0]["timings"]["constructions"])
        self.assertEqual(self.digest, messages[0]["model_sha256"])
        self.assertTrue(all(x["protocol"] == 2 for x in messages))
        for identifier in ["first", "second"]:
            job = [x for x in messages if x.get("id") == identifier]
            self.assertEqual(
                ["progress", "progress", "result"], [x["type"] for x in job]
            )
            self.assertEqual([0.1, 1.0], [x["progress"] for x in job[:-1]])
            self.assertEqual(1, job[-1]["result"]["version"])

    def test_malformed_requests_and_failed_job_do_not_poison_next_job(self):
        bad_audio = self.root / "bad.f32"
        bad_audio.write_bytes(struct.pack("=f", -0.1) * 16000)
        code, messages = self.transact(
            [
                "{bad JSON",
                self.request("old", protocol=1),
                self.request("boolean", frames=True),
                self.request("relative", audio="relative.f32"),
                self.request("failure", audio=str(bad_audio)),
                self.request("good"),
                self.request("good"),
                self.request("after"),
            ]
        )
        self.assertEqual(0, code)
        errors = [x for x in messages if x["type"] == "error"]
        self.assertEqual(6, len(errors))
        self.assertTrue(all(not x.get("fatal", False) for x in errors))
        results = [x for x in messages if x["type"] == "result"]
        self.assertEqual(["good", "after"], [x["id"] for x in results])
        self.assertEqual(results[0]["result"], results[1]["result"])
        self.assertTrue(any("Duplicate" in x["error"] for x in errors))

    def test_oversized_request_terminates_without_processing_following_job(
        self,
    ):
        code, messages = self.transact(
            ["x" * (worker.MAX_REQUEST_BYTES + 1), self.request()]
        )
        self.assertEqual(1, code)
        self.assertEqual(["ready", "error"], [x["type"] for x in messages])
        self.assertIn("64 KiB", messages[-1]["error"])
        self.assertTrue(messages[-1]["fatal"])

    def test_checkpoint_change_reports_current_id_and_exits(self):
        process = self.start_server()
        ready = json.loads(process.stdout.readline())
        self.assertEqual("ready", ready["type"])
        self.checkpoint.write_bytes(b"changed checkpoint")
        output, errors = process.communicate(
            json.dumps(self.request("changed")) + "\n", timeout=10
        )
        self.assertEqual("", errors)
        self.assertEqual(1, process.returncode)
        message = json.loads(output)
        self.assertEqual("error", message["type"])
        self.assertEqual("changed", message["id"])
        self.assertIn("Checkpoint changed", message["error"])
        self.assertTrue(message["fatal"])

    def test_empty_input_loads_once_then_exits_cleanly(self):
        code, messages = self.transact([])
        self.assertEqual(0, code)
        self.assertEqual(["ready"], [x["type"] for x in messages])

    def test_startup_progress_is_flushed_before_model_loading_finishes(self):
        class RecordingOutput(io.StringIO):
            def __init__(self):
                super().__init__()
                self.flushed = []

            def flush(self):
                self.flushed.append(self.getvalue())

        output = RecordingOutput()
        testcase = self

        class LoadingRuntime(FakeRuntime):
            def __init__(self, checkpoint, sha256, progress):
                for value in [0.01, 0.05, 0.1]:
                    progress(value)
                    messages = [
                        json.loads(line)
                        for line in output.getvalue().splitlines()
                    ]
                    testcase.assertTrue(messages)
                    testcase.assertEqual(value, messages[-1]["progress"])
                    testcase.assertEqual(
                        "startup_progress", messages[-1]["type"]
                    )
                    testcase.assertEqual(output.getvalue(), output.flushed[-1])
                    testcase.assertTrue(
                        all(message["protocol"] == 2 for message in messages)
                    )
                    testcase.assertTrue(
                        all("id" not in message for message in messages)
                    )
                super().__init__(checkpoint, sha256, progress)

        code = worker.serve(
            SimpleNamespace(checkpoint=self.checkpoint, sha256=self.digest),
            input_stream=io.StringIO(),
            output_stream=output,
            runtime_factory=LoadingRuntime,
        )
        self.assertEqual(0, code)
        self.assertEqual(4, len(output.flushed))
        messages = [
            json.loads(line) for line in output.getvalue().splitlines()
        ]
        self.assertEqual("ready", messages[-1]["type"])
        self.assertEqual(self.digest, messages[-1]["model_sha256"])

    def test_invalid_startup_progress_is_rejected_before_ready(self):
        for values in [
            [True],
            ["0.1"],
            [float("nan")],
            [float("inf")],
            [-0.01],
            [0.11],
            [0.05, 0.01],
        ]:
            with self.subTest(values=values):

                class InvalidProgressRuntime(FakeRuntime):
                    def __init__(self, checkpoint, sha256, progress):
                        for value in values:
                            progress(value)
                        super().__init__(checkpoint, sha256, progress)

                output = io.StringIO()
                with self.assertRaisesRegex(ValueError, "startup progress"):
                    worker.serve(
                        SimpleNamespace(
                            checkpoint=self.checkpoint, sha256=self.digest
                        ),
                        input_stream=io.StringIO(),
                        output_stream=output,
                        runtime_factory=InvalidProgressRuntime,
                    )
                self.assertNotIn('"type":"ready"', output.getvalue())


